		replacer := strings.NewReplacer(
			"\r", "",
			"\n", "",
		)
		return replacer.Replace(input)
	}

	// Sanitize all user inputs
	safeUserName := sanitizeHTML(userName)
	safeSubject := sanitizeHTML(subject)
	safeFeedbackContent := sanitizeHTML(feedbackContent)

	// Construct email headers with sanitized subject
	emailSubject := fmt.Sprintf("Feedback: %s", sanitizeHeader(subject))
	emailSubject = sanitizeHeader(emailSubject)

	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n",
