package main

import (
	"fmt"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail generates an HTML-formatted email for user feedback.
// It returns the complete email body (including headers) as a string.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate inputs
	if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
		return "", fmt.Errorf("all parameters must be non-empty")
	}

	// Build HTML content for the email body
	htmlBody := fmt.Sprintf(`
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <style>
        body { font-family: Arial, sans-serif; margin: 20px; }
        .header { background-color: #4CAF50; color: white; padding: 10px; text-align: center; }
        .content { margin: 20px 0; }
        .field { margin-bottom: 15px; }
        .field-label { font-weight: bold; color: #333; }
        .field-value { margin-left: 10px; color: #555; }
        .footer { margin-top: 20px; font-size: 12px; color: #888; }
    </style>
</head>
<body>
    <div class="header">
        <h2>New User Feedback Submission</h2>
    </div>
    <div class="content">
        <div class="field">
            <span class="field-label">Username:</span>
            <span class="field-value">%s</span>
        </div>
        <div class="field">
            <span class="field-label">Subject:</span>
            <span class="field-value">%s</span>
        </div>
        <div class="field">
            <span class="field-label">Feedback Content:</span>
            <div class="field-value" style="margin-top:5px; padding:10px; background-color:#f9f9f9; border:1px solid #ddd;">
                %s
            </div>
        </div>
    </div>
    <div class="footer">
        <p>This email was generated automatically from the user feedback system.</p>
    </div>
</body>
</html>`, userName, subject, feedbackContent)

	// Construct the full email with headers
	headers := make(map[string]string)
	headers["From"] = fromAddr
	headers["To"] = toAddr
	headers["Subject"] = subject
	headers["MIME-Version"] = "1.0"
	headers["Content-Type"] = "text/html; charset=\"UTF-8\""

	// Build header string
	var headerStr strings.Builder
	for key, value := range headers {
		headerStr.WriteString(fmt.Sprintf("%s: %s\r\n", key, value))
	}

	// Combine headers and body
	emailBody = headerStr.String() + "\r\n" + htmlBody
	return emailBody, nil
}

// Example usage (for testing purposes)
func main() {
	// Example parameters
	fromAddr := "noreply@example.com"
	toAddr := "support@example.com"
	userName := "JohnDoe"
	subject := "App Crash Report"
	feedbackContent := "The application crashes every time I try to upload a file larger than 10MB. Please fix this issue."

	// Build the email
	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		fmt.Printf("Error building email: %v\n", err)
		return
	}

	// Print the email body (for demonstration)
	fmt.Println("Generated Email Body:")
	fmt.Println(emailBody)

	// To actually send the email, you would use smtp.SendMail:
	// smtp.SendMail("smtp.example.com:587", smtp.PlainAuth("", "username", "password", "smtp.example.com"), fromAddr, []string{toAddr}, []byte(emailBody))
}

