func sendFeedbackEmail(smtpHost string, smtpPort string, smtpUser string, smtpPass string, fromAddr string, toAddr string, userName string, subject string, feedbackContent string) error {
	// Build the email body
	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
