	var result strings.Builder
	length := len(data)
	for i := 0; i < length; i += 3 {
		var val uint32
		if i < length {
			val |= uint32(data[i]) << 16
		}
		if i+1 < length {
			val |= uint32(data[i+1]) << 8
		}
		if i+2 < length {
