// BuildFeedbackEmail generates an HTML email body for user feedback
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate inputs
	if fromAddr == "" || toAddr == "" || userName == "" || subject == "" || feedbackContent == "" {
		return "", fmt.Errorf("all parameters must be non-empty")
	}

	// Build HTML email body
	var body strings.Builder

	// Email headers
	body.WriteString(fmt.Sprintf("From: %s\r\n", fromAddr))
	body.WriteString(fmt.Sprintf("To: %s\r\n", toAddr))
	body.WriteString(fmt.Sprintf("Subject: User Feedback: %s\r\n", subject))
	body.WriteString("MIME-Version: 1.0\r\n")
	body.WriteString("Content-Type: text/html; charset=\"UTF-8\"\r\n")
	body.WriteString("\r\n")

	// HTML content
	body.WriteString("<!DOCTYPE html>\r\n")
	body.WriteString("<html>\r\n")
	body.WriteString("<head>\r\n")
	body.WriteString("<meta charset=\"UTF-8\">\r\n")
	body.WriteString("<style>\r\n")
	body.WriteString("body { font-family: Arial, sans-serif; margin: 20px; }\r\n")
	body.WriteString(".feedback-container { border: 1px solid #ccc; padding: 20px; border-radius: 5px; }\r\n")
	body.WriteString(".field { margin-bottom: 15px; }\r\n")
	body.WriteString(".field-label { font-weight: bold; color: #333; }\r\n")
	body.WriteString(".field-value { margin-top: 5px; padding: 10px; background-color: #f9f9f9; border-radius: 3px; }\r\n")
	body.WriteString("</style>\r\n")
	body.WriteString("</head>\r\n")
	body.WriteString("<body>\r\n")
	body.WriteString("<div class=\"feedback-container\">\r\n")
	body.WriteString("<h2>New User Feedback</h2>\r\n")
	body.WriteString("<div class=\"field\">\r\n")
	body.WriteString("<div class=\"field-label\">User Name:</div>\r\n")
	body.WriteString(fmt.Sprintf("<div class=\"field-value\">%s</div>\r\n", htmlEscape(userName)))
	body.WriteString("</div>\r\n")
	body.WriteString("<div class=\"field\">\r\n")
	body.WriteString("<div class=\"field-label\">Subject:</div>\r\n")
	body.WriteString(fmt.Sprintf("<div class=\"field-value\">%s</div>\r\n", htmlEscape(subject)))
	body.WriteString("</div>\r\n")
	body.WriteString("<div class=\"field\">\r\n")
	body.WriteString("<div class=\"field-label\">Feedback Content:</div>\r\n")
	body.WriteString(fmt.Sprintf("<div class=\"field-value\">%s</div>\r\n", htmlEscape(feedbackContent)))
	body.WriteString("</div>\r\n")
	body.WriteString("</div>\r\n")
	body.WriteString("</body>\r\n")
	body.WriteString("</html>\r\n")

	return body.String(), nil
}

// htmlEscape escapes special HTML characters to prevent XSS
func htmlEscape(s string) string {
	replacer := strings.NewReplacer(
		"&", "&amp;",
		"<", "&lt;",
		">", "&gt;",
		"\"", "&quot;",
		"'", "&#39;",
	)
	return replacer.Replace(s)
}

