package main

import (
	"fmt"
	"html"
	"net/mail"
	"strings"
)

// BuildFeedbackEmail constructs a complete RFC 5322-compliant email message
// with HTML body containing user feedback information.
// The returned emailBody includes headers and body, ready to be sent via smtp.SendMail.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Basic validation
	if fromAddr == "" || toAddr == "" {
		return "", fmt.Errorf("fromAddr and toAddr must not be empty")
	}

	// Validate email addresses format (optional but good practice)
	if _, err := mail.ParseAddress(fromAddr); err != nil {
		return "", fmt.Errorf("invalid fromAddr: %w", err)
	}
	if _, err := mail.ParseAddress(toAddr); err != nil {
		return "", fmt.Errorf("invalid toAddr: %w", err)
	}

	// Sanitize user input to prevent XSS and injection attacks
	safeUserName := html.EscapeString(userName)
	safeSubject := html.EscapeString(subject)
	safeFeedbackContent := html.EscapeString(feedbackContent)

	// Construct email headers
	emailSubject := fmt.Sprintf("Feedback: %s", safeSubject)

	// Handle non-ASCII characters in subject using RFC 2047 encoded-word
	encodedSubject := encodeRFC2047(emailSubject)

	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n",
		fromAddr,
		toAddr,
		encodedSubject,
	)

	// Construct HTML body with sanitized content
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>User Feedback</title>
</head>
<body>
  <h2>User Feedback Received</h2>
  <p><strong>Submitted by:</strong> %s</p>
  <p><strong>Subject:</strong> %s</p>
  <div><strong>Message:</strong><br>
    <pre style="font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 10px; border: 1px solid #ddd;">%s</pre>
  </div>
</body>
</html>`,
		safeUserName,
		safeSubject,
		safeFeedbackContent,
	)

	// Combine headers and body
	emailMessage := headers + htmlBody

	return emailMessage, nil
}

// encodeRFC2047 encodes a string according to RFC 2047 for use in email headers
func encodeRFC2047(s string) string {
	// Check if encoding is needed (contains non-ASCII characters)
	for _, r := range s {
		if r > 127 {
			// Use base64 encoding for non-ASCII subjects
			return fmt.Sprintf("=?UTF-8?B?%s?=", base64Encode([]byte(s)))
		}
	}
	// ASCII only - no encoding needed but escape special characters
	return escapeHeaderString(s)
}

// base64Encode performs base64 encoding (simplified for demonstration)
func base64Encode(data []byte) string {
	const base64Chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var result strings.Builder
	for i := 0; i < len(data); i += 3 {
		var val int
		if i+0 < len(data) {
			val |= int(data[i]) << 16
		}
		if i+1 < len(data) {
			val |= int(data[i+1]) << 8
		}
		if i+2 < len(data) {
			val |= int(data[i+2])
		}

		result.WriteByte(base64Chars[(val>>18)&0x3F])
		result.WriteByte(base64Chars[(val>>12)&0x3F])
		if i+1 < len(data) {
			result.WriteByte(base64Chars[(val>>6)&0x3F])
		} else {
			result.WriteByte('=')
		}
		if i+2 < len(data) {
			result.WriteByte(base64Chars[val&0x3F])
		} else {
			result.WriteByte('=')
		}
	}
	return result.String()
}

// escapeHeaderString escapes special characters in email headers
func escapeHeaderString(s string) string {
	// Replace backslash and double quotes for safety
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "\"", "\\\"")
	return s
}

